import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const tradePreferencesApi = createApi({
    reducerPath: 'tradePreferencesApi',
    tagTypes: ['tradePreferences'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getTradePreferences: builder.query({
            query: () => ({
                url: '/trade-preferences',
                method: RequestMethods.GET,
            }),
            providesTags: ['tradePreferences'],
        }),
        setTradePreferences: builder.mutation({
            query: (body) => ({
                url: '/trade-preferences',
                method: RequestMethods.PUT,
                body,
            }),
            invalidatesTags: ['tradePreferences'],
        }),
    }),
});
export const { useGetTradePreferencesQuery, useSetTradePreferencesMutation, } = tradePreferencesApi;
